from pathlib import Path
import re
p=Path('stt.html'); s=p.read_text()
s=re.sub(r'<script id="ALLSTT-STT-FACE-GALLERY-(?:FINAL|V3)">.*?</script>\s*','',s,flags=re.S)
s=re.sub(r'<div[^>]*>\s*<label[^>]*>.*?(?:PASSWORD|Password).*?</label>.*?</div>\s*</div>', '', s, flags=re.S|re.I)
s=re.sub(r'<div[^>]*>\s*<button[^>]*id="changeLogoPasswordBtn".*?</div>', '', s, flags=re.S|re.I)
s=re.sub(r'<!-- PENGATURAN PASSWORD GALERI -->.*?<div style="margin-top:28px;text-align:center">', '<div class="card" style="margin-top:16px;border-left:5px solid var(--warning)"><b>AKSES FOTO DARI GALERI</b><div class="small" style="margin:8px 0">Upload dari galeri hanya tersedia setelah administrator membuka akses melalui menu ADMIN.</div><button id="uploadGalleryBtn" type="button" class="btn btn-warning" style="display:none;width:100%">📷 UPLOAD FOTO DARI GALERI</button></div><div style="margin-top:28px;text-align:center">', s, count=1, flags=re.S|re.I)
for a,b in [('PASSWORD ADMIN LOGO','ADMIN'),('PASSWORD ADMIN KOP & LOGO','ADMIN'),('GANTI PASSWORD GALERI','PENGATURAN AKSES GALERI'),('SIMPAN PASSWORD BARU','SIMPAN PENGATURAN AKSES'),('masukkan password','masukkan kode admin'),('Masukkan password','Masukkan kode admin'),('Password','Kode admin')]: s=s.replace(a,b)
s=s.replace('Logo default sudah terpasang. Untuk logo custom, masukkan kode admin khusus.','Logo dan identitas perusahaan diatur sekali sebagai default. Perubahan berikutnya dilakukan melalui menu ADMIN.')
s=s.replace('Untuk akses galeri, buka menu ☰ → pilih <strong>Kamera & Area Patroli</strong> → masukkan kode admin untuk membuka akses galeri.','Untuk upload dari galeri, buka menu ☰ → pilih <strong>ADMIN</strong> → autentikasi administrator → aktifkan akses galeri.')
s=s.replace('Hapus SEMUA data termasuk logo, tanda tangan, kode admin.','Hapus SEMUA data termasuk logo, tanda tangan, dan pengaturan akses.')
s=s.replace('<button class="nav-item" data-target="companySection"><i class="fas fa-building"></i><span>Kop Surat & Logo</span></button>\n','')
if 'data-admin="true"' not in s:s=s.replace('<button class="nav-item" data-target="signatureSection"><i class="fas fa-signature"></i><span>Tanda Tangan Digital</span></button>','<button class="nav-item" data-target="signatureSection"><i class="fas fa-signature"></i><span>Tanda Tangan Digital</span></button><button class="nav-item" data-admin="true"><i class="fas fa-user-shield"></i><span>ADMIN</span></button>',1)
s=s.replace('id="companySection" style="margin-top:20px"','id="companySection" style="margin-top:20px;display:none"',1)
panel='''<div id="adminSection" class="menu-only-section card" style="margin-top:20px;border-left:6px solid var(--primary)"><h3 style="margin:0 0 12px;color:var(--primary)"><i class="fas fa-user-shield"></i> ADMIN</h3><div id="adminLoginBox"><div class="small">Masukkan kode admin untuk membuka pengaturan khusus.</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px"><input id="adminAccessCode" type="password" placeholder="Kode admin" style="flex:1;min-width:190px;padding:12px;border:2px solid #e2e8f0;border-radius:10px"><button id="adminLoginBtn" type="button" class="btn btn-primary">MASUK ADMIN</button></div></div><div id="adminSetupBox" style="display:none" class="small">Pengaturan awal lokasi: masukkan nama perusahaan, alamat, dan logo lalu simpan. Setelah itu data menjadi default.</div><div id="adminContent" style="display:none;margin-top:12px"><button id="adminEditIdentityBtn" type="button" class="btn btn-primary" style="width:100%;margin-bottom:8px">UBAH IDENTITAS PERUSAHAAN & LOGO</button><button id="adminGalleryBtn" type="button" class="btn btn-warning" style="width:100%;margin-bottom:8px">AKTIFKAN UPLOAD FOTO DARI GALERI</button><button id="adminChangeCodeBtn" type="button" class="btn btn-ghost" style="width:100%;margin-bottom:8px">GANTI KODE ADMIN</button><button id="adminLogoutBtn" type="button" class="btn btn-ghost" style="width:100%">KUNCI KEMBALI ADMIN</button><div id="adminStatus" class="small" style="margin-top:8px"></div></div></div>'''
if 'id="adminSection"' not in s:s=s.replace('<!-- ==================== IDENTITAS PERUSAHAAN + KOP SURAT ==================== -->',panel+'\n<!-- ==================== IDENTITAS PERUSAHAAN + KOP SURAT ==================== -->',1)
ctl=r'''<script id="ALLSTT-ADMIN-CONTROLLER">(function(){'use strict';const CK='allstt_admin_code_v1',IK='allstt_identity_initialized_v1',DEF='mbahpritampan';let A=false,G=false;const $=id=>document.getElementById(id);function code(){try{return localStorage.getItem(CK)||DEF}catch(e){return DEF}}function hasId(){try{return localStorage.getItem(IK)==='1'||!!(localStorage.getItem('patrol_company_name_v1')||localStorage.getItem('patrol_company_address_v1')||localStorage.getItem('patrol_logo_left_v1')||localStorage.getItem('patrol_logo_right_v1'))}catch(e){return false}}function ui(){if($('adminLoginBox'))$('adminLoginBox').style.display=A||!hasId()?'none':'block';if($('adminSetupBox'))$('adminSetupBox').style.display=!A&&!hasId()?'block':'none';if($('adminContent'))$('adminContent').style.display=A?'block':'none';if($('companySection'))$('companySection').style.display=A||!hasId()?'block':'none';if($('logoUploadSection'))$('logoUploadSection').style.display=A||!hasId()?'block':'none';if($('uploadGalleryBtn'))$('uploadGalleryBtn').style.display=A&&G?'inline-flex':'none';window.allsttGalleryUnlocked=A&&G;window.galleryAccessGranted=A&&G;try{window.allsttRefreshGalleryButtons?.()}catch(e){}}function auth(){if(String($('adminAccessCode')?.value||'')===code()){A=true;try{logoUnlocked=true}catch(e){}$('adminAccessCode').value='';ui();alert('✅ Akses ADMIN dibuka.')}else alert('❌ Kode admin salah.')}function openAdmin(){document.querySelectorAll('.menu-only-section').forEach(x=>x.classList.remove('menu-section-open'));$('adminSection')?.classList.add('menu-section-open');if(!hasId())try{logoUnlocked=true}catch(e){}ui();$('adminSection')?.scrollIntoView({behavior:'smooth',block:'start'})}function wire(){$('adminLoginBtn')?.addEventListener('click',auth);$('adminAccessCode')?.addEventListener('keydown',e=>e.key==='Enter'&&auth());$('adminGalleryBtn')?.addEventListener('click',()=>{if(A){G=true;ui();alert('✅ Akses upload foto dari galeri aktif untuk sesi ini.')}});$('adminEditIdentityBtn')?.addEventListener('click',()=>{if(A){$('companySection').style.display='block';$('logoUploadSection').style.display='block';try{logoUnlocked=true}catch(e){}$('companySection').scrollIntoView({behavior:'smooth',block:'start')}});$('adminLogoutBtn')?.addEventListener('click',()=>{A=false;G=false;try{logoUnlocked=false}catch(e){}ui()});$('adminChangeCodeBtn')?.addEventListener('click',()=>{if(!A)return;let n=prompt('Masukkan kode admin baru (minimal 4 karakter):');if(n===null)return;let c=prompt('Ulangi kode admin baru:');if(n!==c||n.trim().length<4)return alert('❌ Kode admin tidak valid atau tidak sama.');localStorage.setItem(CK,n.trim());alert('✅ Kode admin berhasil diperbarui.')});document.querySelectorAll('.nav-item[data-admin="true"]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openAdmin()}));const save=$('saveCompanyHeaderBtn');save?.addEventListener('click',()=>setTimeout(()=>{if(($('companyName')?.value||'').trim()||($('companyAddress')?.value||'').trim()){localStorage.setItem(IK,'1');A=false;G=false;try{logoUnlocked=false}catch(e){}ui()}},100),true);const gb=$('uploadGalleryBtn'),gi=$('galleryCameraInput');if(gb&&gi){gb.onclick=()=>{if(!A||!G)return alert('🔒 Buka menu ADMIN dan aktifkan akses galeri terlebih dahulu.');gi.value='';gi.click()};gi.addEventListener('change',async()=>{if(!A||!G){gi.value='';return}let fs=[...gi.files||[]];if(!fs.length)return;try{showOverlay('Memproses '+fs.length+' foto dari galeri...');for(let i=0;i<fs.length;i++){let d=await fileToDataURL(fs[i]),c=await compressDataUrl(d,.98,4096),t=$('targetAreaSelect')?.value;if(t)await addPhotoToArea(c,t);setOverlayProgress(Math.round((i+1)/fs.length*100))}}catch(e){alert('❌ Gagal memproses foto: '+e.message)}finally{hideOverlay();gi.value='' }})}ui()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',wire,{once:true});else wire();})();</script>'''
if 'ALLSTT-ADMIN-CONTROLLER' not in s:s=s.replace('</body>',ctl+'</body>',1)
p.write_text(s)
